        Check(!TargetOrder.Valid(["Focus", "Selected", "PartyMouseover"], false), "Enemy override order rejects unsupported sources");
        var reordered = TargetOrder.Apply([new(TargetSource.Selected, 1), new(TargetSource.Explicit, 2), new(TargetSource.Focus, 3)],
