        Check(GunbreakerPlan.Choose(gunbreaker with { ExpiringProc = 2 }) == 2, "A usable expiring Sonic Break is not dropped for a new chain");
        Check(GunbreakerPlan.Choose(new(0, 0, 0, 0, 0, 0, 0, 8)) == 8, "Manual holds leave the basic GCD available");
        Check(GunbreakerPlan.Choose(new(0, 0, 0, 0, 0, 0, 0, 0)) == 0, "No eligible GCD is explicit");
