        Check(!DanceBudget.CanStart(dance with { Downtime = 5 }), "Do not start a dance whose finish misses known uptime");
        Check(DanceBudget.CanStart(dance with { Downtime = null }), "Missing forecast retains the existing dance schedule");
        Check(DanceBudget.ExpiresBeforeNext(3, .5f, 2.5f), "Ready proc expires before the second available GCD");
