        Check(MonkPhase.Next(monk with { First = MonkForm.Raptor }) == MonkForm.Coeurl, "Manual Raptor first does not duplicate Raptor on the second press");
        Check(MonkPhase.Next(monk with { First = MonkForm.Raptor, Second = MonkForm.Coeurl }) == MonkForm.Opo, "Manual solar ordering completes the missing form");
