        Check(!CastBudget.Fits(castBudget with { TargetReturns = 2 }), "Do not spend a short downtime on a long motif");
        Check(CastBudget.Fits(castBudget with { Cast = 0, Moving = true, SafeCastWindow = 0 }), "Instant preparation does not need a stationary cast window");
        Check(CastBudget.Fits(castBudget with { SafeCastWindow = null, TargetReturns = null }), "Unavailable encounter data preserves ordinary readiness");
        var castForecast = new EncounterForecast(1000, 1, "module", null, null, null, null, MaxCastTime:0);
        Check(castForecast.RemainingLimit(castForecast.MaxCastTime, 1100, 1) == 0, "A zero cast window stays restrictive until refreshed or expired");
        Check(castForecast.RemainingLimit(castForecast.MaxCastTime, 2600, 1) is null, "Stale cast limits cannot suppress casts indefinitely");
        var coverage = new MitigationCoverageInput([6, 6, 6, 0], 3);
        Check(MitigationCoverage.CoversHit(coverage), "Observed defense covering three quarters of the party can defer forecast mitigation");
        Check(!MitigationCoverage.CoversHit(coverage with { Impact = 6 }), "A defense expiring before impact cannot suppress prevention");
        Check(!MitigationCoverage.CoversHit(coverage with { Impact = null }), "Unknown impact timing must not assume existing mitigation lasts");
        Check(!MitigationCoverage.CoversHit(coverage with { Remaining = [6, 0, 0, 0] }), "One protected player does not imply party coverage");
        Check(!PvpEligibility.CanDamage(true, false, 0, true, 0), "Guard bypass never bypasses invulnerability");
        Check(!PvpEligibility.CanDamage(false, true, 0, true, 0), "Guard bypass does not bypass Hardened Scales");
        Check(PvpEligibility.CanDamage(false, false, 4, true, 0), "Reviewed Guard bypass remains eligible");
        Check(!PvpEligibility.CanDamage(false, false, 4, false, 0), "Ordinary instant damage waits for Guard");
