        Check(!adaptive.Select(true, 1, 3, true), "Unaccepted icon previews cannot latch a sequence");
        adaptive.Confirm(true);
        Check(adaptive.Select(true, 1, 3, true), "Accepted sequence retains area choice despite changing enemy count");
        Check(!adaptive.Select(true, 1, 3, false), "Completed sequence can return to single target");
