        var targetInput = new TargetSelectionInput(Vector3.Zero,1,heal,policy,party,party,[new(TargetSource.Focus,1)]);
        var capture = new Newtonsoft.Json.Linq.JObject { ["DecisionSamples"] = new Newtonsoft.Json.Linq.JArray(
            new Newtonsoft.Json.Linq.JObject { ["Provider"]="DRG.LifeSurge",["Input"]=Newtonsoft.Json.Linq.JToken.FromObject(drg),["Output"]=DrgPreparation.LifeSurge(drg) },
            new Newtonsoft.Json.Linq.JObject { ["Provider"]="Preparation",["Input"]=Newtonsoft.Json.Linq.JToken.FromObject(input),["Output"]=Newtonsoft.Json.Linq.JToken.FromObject(PreparationPolicy.Select(input)!) },
            new Newtonsoft.Json.Linq.JObject { ["Provider"]="Target",["Input"]=Newtonsoft.Json.Linq.JToken.FromObject(targetInput),["Output"]=Newtonsoft.Json.Linq.JToken.FromObject(TargetSelection.Select(targetInput)) }) };
        Check(DecisionReplay.Run(Newtonsoft.Json.Linq.JObject.Parse(capture.ToString()))==3,"Exported immutable decisions must replay through JSON without live selectors");
        capture["DecisionSamples"]![0]!["Output"] = false;
        bool mismatch=false;
        try { DecisionReplay.Run(capture); } catch(InvalidDataException) { mismatch=true; }
        Check(mismatch,"Replay must detect a changed recorded result");
        var chain = new PreparationSequence();
        var deployPlan = new SelectionDecision(16542,185,42,16542,"Recitation, Adlo, Deployment",1000,1,0,3585);
        chain.Press(deployPlan);
        Check(chain.Current(1001,1) is null,"Displaying or pressing a chain must not accept its preparation");
        chain.Confirm(16542,1100,1,false);
        Check(chain.Current(1101,1)?.PlannedGcd==185 && chain.Current(1101,1)?.Recipient==42,"Recitation must retain the selected Adlo recipient");
        for(int i=0;i<20;i++)Check(chain.Current(1102,1)?.PlannedGcd==185,"Repeated previews advanced the shield chain");
        chain.Confirm(185,1500,1,true);
        Check(chain.Current(1501,1)?.PlannedGcd==3585 && chain.Current(1501,1)?.Recipient==42,"Confirmed shield must retain its recipient for Deployment");
        chain.Confirm(3585,1700,1,false);
        Check(chain.Current(1701,1) is null,"Completed Deployment must not repeat");
        chain.Press(deployPlan with{Action=185,Preparation=0});
        chain.Confirm(185,1800,1,true);
        Check(chain.Current(1801,1)?.PlannedGcd==3585,"Adlo without Recitation must still retain its Deployment continuation");
        chain.Reset();chain.Press(deployPlan);
        chain.Confirm(16542,1900,1,false);
        chain.Confirm(185,2000,1,true,recipientConfirmed:false);
        Check(chain.Current(2001,1) is null,"A shield on another recipient must cancel the planned Deployment");
        chain.Press(deployPlan with{ObservedAt=2100});chain.Confirm(16542,2200,1,false);
        chain.Confirm(17869,2300,1,true);
        Check(chain.Current(2301,1) is null,"An unrelated preparation-consuming spell must cancel the healing chain");
        var pendingHealth = new PendingHealth();
        pendingHealth.Observe(10,1,0,40,1000);
        pendingHealth.Observe(10,2,0,30,1000);
        pendingHealth.Observe(10,1,0,40,1001);
        Check(pendingHealth.Count==2 && pendingHealth.Project(30,100,1,1001)==70,"Repeated confirmed packets must not double-count pending healing");
        for(int i=0;i<20;i++)Check(pendingHealth.Project(30,100,1,1002)==70 && pendingHealth.Count==2,"Health previews must be non-consuming");
        pendingHealth.Acknowledge(10,1);
        Check(pendingHealth.Project(70,100,1,1100)==70 && pendingHealth.Project(30,100,2,1100)==60,"One recipient's acknowledgement must not remove another recipient's pending heal");
        pendingHealth.Observe(11,2,0,-200,1200);
        Check(pendingHealth.Project(30,100,2,1201)==0,"Pending damage must saturate at zero");
        pendingHealth.Observe(12,3,0,200,1200);
        Check(pendingHealth.Project(90,100,3,1201)==100,"Pending overheal must saturate at maximum health");
        Check(pendingHealth.Project(30,100,2,2700)==30,"Unacknowledged effects must expire rather than suppress healing indefinitely");
        pendingHealth.Tick(2700);Check(pendingHealth.Count==0,"Effect observer must remove expired records");
        for(uint i=0;i<2050;i++)pendingHealth.Observe(i,1,0,1,3000+i);
        Check(pendingHealth.Count==2048,"Pending effects must have a bounded memory footprint");
        pendingHealth.Reset();Check(pendingHealth.Count==0,"Context reset must discard old encounter effects");
        budget.Observe("raidwide",true,5000,2,0,null);
        var unknownWindow = budget.Available("raidwide")!;
        budget.Observe("raidwide",true,5100,2,0,4,"cast:100:200");
        Check(budget.Available("raidwide")?.Id==unknownWindow.Id && budget.Available("raidwide")?.DueAt==9100,"Acquiring cast timing must enrich the current event without granting another cooldown");
        budget.Confirm(unknownWindow.Id);
        budget.Observe("raidwide",true,5200,2,0,3.9f,"cast:101:200");
        Check(budget.Available("raidwide") is not null,"Another caster's simultaneous event needs independent identity");
        budget.Observe("tankbuster",true,5300,2,42,null,"vfx:1");
        budget.Confirm(budget.Available("tankbuster")!.Id);
        budget.Observe("tankbuster",true,5400,2,42,null,"vfx:2");
        Check(budget.Available("tankbuster") is not null,"A new tankbuster marker on the same tank must not reuse the spent event");
        return checks;
    }
}
